INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.51', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'fashion_men' AS code, '这件衬衫175 130斤能穿吗' AS question, '亲，175身高130斤建议选M码哦~这款衬衫是标准版型，M码肩宽46cm胸围104cm衣长71cm，您平时穿M码的话这款正好。要是您喜欢宽松点可以拿L码，喜欢修身就选M码。衬衫领围M码是39cm，您可以量下自己常穿的衬衫领围对比下，这样选码更准。我们支持7天无理由退换，尺码不合适包换邮费我们出，让您买得放心！已售上千件尺码反馈很准，有任何问题随时联系我处理！' AS answer, '尺码,衬衫,身高体重,版型,退换' AS tags, '根据身高体重推荐尺码并承诺退换' AS source_summary, 88 AS score
  UNION ALL SELECT 'fashion_men', 'T恤是什么材质的会起球吗', '您好！这款T恤采用95%精梳棉加5%氨纶面料，克重220g，手感柔软亲肤透气性好。精梳棉比普通棉纤维更长更细腻，不易起球不易变形，穿着更舒适。氨纶增加弹性活动更自如。正常机洗不会起球，建议反面冷水洗避免暴晒。已售800多件回头客很多，质量您放心，有任何问题随时联系处理！我们做长久生意不坑人，每件衣服都经过质检才发货，让您买得放心穿得舒心。', '材质,T恤,精梳棉,起球,洗涤', '详细说明材质并给出洗护建议', 90
  UNION ALL SELECT 'fashion_men', '这件外套版型是宽松还是修身的', '亲，这款外套是微宽松版型哦~比修身款舒服活动自如，比oversize利落不显臃肿，适合大多数身材穿着。肩部做了微落肩设计，抬手不紧绷活动方便。喜欢修身效果选小一码，喜欢休闲感选正码就好。我给您发张尺码表参考下胸围肩宽数据。下单48小时内发货，试穿不满意支持退换，购物无忧！已售500多件版型反馈很好，您放心选。', '版型,外套,宽松,修身,尺码', '说明版型特点并给出选码建议', 85
  UNION ALL SELECT 'fashion_men', '裤子长度多少我腿比较长怕短了', '您好！这款裤子M码裤长102cm，L码104cm，XL码106cm。您可以根据身高参考，175以下选M，175到180选L，180以上选XL。裤长是常规版型大多数人穿正好。要是您腿特别长也可以选大一码，裤腰稍微改下就好。我们支持7天退换，收到试穿不合适可以换码，邮费我们承担！已售上千条裤长反馈很准，您把身高体重告诉我我帮您参考选码。', '裤长,裤子,身高,尺码,退换', '提供各码裤长数据并给选码建议', 86
  UNION ALL SELECT 'fashion_men', '这件夹克是正品吗能验货吗', '亲，正品支持专柜验货假一赔十！您可以拿去专柜对比或者上得物鉴定，有问题全包退邮费我都出。我们做长久生意不干一锤子买卖，每个细节都经得起检验。吊牌洗标包装都是原厂的，您收到一看就知道。已售400多件正品问题零投诉。放心拍，有任何疑问随时找我！咱们做生意凭良心，绝对不会拿假货忽悠人。', '正品,验货,夹克,假一赔十', '承诺正品验货并承担退换邮费', 92
  UNION ALL SELECT 'fashion_men', '卫衣冬天穿够厚吗里面要加衣服吗', '您好！这款卫衣是加绒款内里复合抓绒，克重380g，0度以上单穿就够暖。要是您那边零下可以里面搭件保暖内衣完全不显臃肿。卫衣版型微宽松里面加衣服也不会紧。北方冬天户外可能需要搭外套，南方单穿完全OK。已售上千件冬季爆款，保暖性反馈很好放心入！有任何穿着问题随时联系我，包您满意。', '卫衣,厚度,加绒,保暖,冬季', '说明保暖性能并给搭配建议', 88
  UNION ALL SELECT 'fashion_men', '西装能不能机洗干洗太贵了', '亲，这款西装建议干洗哦~因为含有羊毛成分机洗容易缩水变形。不过也不用每次都干洗，穿3到4次后干洗一次就行，平时挂起来通风散味就好。局部脏了可以用湿布轻擦。干洗一次十几块一个季度洗2到3次够了算下来也不贵。西装保养好了穿好几年都不变形很划算！已售300多套保养反馈很好，有问题随时联系我。', '西装,干洗,机洗,保养,羊毛', '说明干洗必要性并给保养省钱建议', 87
  UNION ALL SELECT 'fashion_men', '衬衫领子会不会软塌塌的立不起来', '您好！这款衬衫领子内置了可拆卸领撑，领型挺括有型不会软塌。领面用了粘合衬工艺洗后也不容易变形。日常穿着领型很正商务场合也撑得住。建议洗后领子整理好再晾，扣子扣上保持领型。要是不小心领子变形了熨斗低温熨一下就恢复挺括了。已售600多件领型反馈很好。质量您放心，有问题随时联系！', '衬衫,领型,领撑,挺括,保养', '说明领型工艺并给保养建议', 85
  UNION ALL SELECT 'fashion_men', '这个T恤洗了会不会缩水', '亲，这款T恤做过预缩水处理，正常洗涤缩水率在3%以内基本看不出变化。建议冷水轻柔机洗或手洗，别用热水别烘干自然晾干就好。精梳棉面料稳定性好洗后不会变形不会缩水。已售上千条洗后反馈都很好您放心入手。有任何缩水问题联系我们包退换，质量有保障！咱们做生意凭良心，每件都经过质检才发货。', 'T恤,缩水,洗涤,精梳棉', '说明预缩处理并给洗涤建议', 86
  UNION ALL SELECT 'fashion_men', '外套防水吗下雨天能穿吗', '您好！这款外套面料做了防泼水处理，小雨毛毛雨完全没问题水珠会滑落不渗透。但大雨暴雨不建议长时间淋毕竟不是专业冲锋衣。日常通勤遇雨完全OK到室内抖一抖水珠就掉了。面料本身也防风秋冬穿很挡风。已售500多件户外通勤党反馈很好放心拍！有任何问题随时联系我处理，让您买得放心。', '外套,防水,防泼水,防风,通勤', '说明防水等级并给使用场景建议', 87
  UNION ALL SELECT 'fashion_men', '这条牛仔裤腰围多大我穿31的能穿吗', '亲，这款牛仔裤M码腰围32英寸合31到32腰围穿，L码腰围34英寸合33到34腰围穿。您平时穿31的话选M码正好，略松一点点很舒服。牛仔裤本身有点弹力腰围活动空间也够。建议您量下自己常穿裤子的平铺腰围对比下更准。支持退换不合适可以换码！已售800多条腰围反馈很准，放心拍。', '牛仔裤,腰围,尺码,弹力,退换', '根据腰围推荐尺码并引导测量对比', 86
  UNION ALL SELECT 'fashion_men', 'POLO衫领子会变形吗洗多了会不会卷', '您好！这款POLO衫领子用了双层粘合衬工艺，挺括有型不易变形不易卷边。建议洗后领子整理平整平铺晾干，别用衣架挂着晾容易拉变形。正常机洗几十次领型还是正的。已售600多件反馈领型保持很好。要是领子有轻微变形熨一下就恢复了，质量放心！有问题随时联系我包退换。', 'POLO衫,领型,变形,洗涤,保养', '说明领型工艺并给洗护建议', 85
  UNION ALL SELECT 'fashion_men', '风衣长了点能改短吗', '亲，风衣是可以改短的哦~建议您拿到裁缝店改，一般改短10cm以内收费20到30块。改短后下摆比例还是协调的不影响版型。要是您不想改也可以选小一码，不过小一码胸围肩围也会小。您把身高体重告诉我我帮您参考下选码。支持退换要是不合适可以换！已售300多件改短反馈很好，放心拍。', '风衣,改短,尺码,版型,退换', '提供改短建议并帮助选码', 84
  UNION ALL SELECT 'fashion_men', '西裤会不会起褶皱坐久了', '您好！这款西裤用了抗皱面料，含有少量涤纶成分提升抗皱性。正常坐办公室一天起来拍一拍褶皱就没了，不会像纯棉那样死褶。要是坐久了有些褶皱挂一晚或者蒸汽熨一下就平整了。面料垂感也很好穿着显精神。已售300多条职场党反馈很好，放心入！有任何问题随时联系我处理。', '西裤,褶皱,抗皱,面料,职场', '说明抗皱性能并给打理建议', 86
  UNION ALL SELECT 'fashion_men', '这件羽绒服蓬松度多少暖不暖', '亲，这款羽绒服填充量150g蓬松度600，属于中暖款，0度到零下10度穿完全OK。要是您那边零下15度以下建议选加厚款。羽绒服轻便保暖不显臃肿，版型也很时尚。面料做了防钻绒处理不会跑毛。已售上千件冬季爆款保暖反馈很好。支持退换，有任何问题随时联系！您把当地气温告诉我我帮您参考。', '羽绒服,蓬松度,保暖,填充量,冬季', '说明保暖参数并给适用温度建议', 89
  UNION ALL SELECT 'fashion_men', '毛衣会不会扎人皮肤敏感能穿吗', '您好！这款毛衣是美利奴羊毛的，纤维细度19微米比普通羊毛细很多，不扎人亲肤性好。皮肤敏感也能直接贴身穿。美利奴羊毛保暖透气还抗菌不易起球。建议冷水手洗或干洗别机洗容易缩水。已售500多件敏感肌买家反馈很好。有任何不适联系我们包退换！咱们不坑人，质量有保障。', '毛衣,羊毛,扎人,皮肤敏感,美利奴', '说明材质亲肤性并给洗护建议', 88
  UNION ALL SELECT 'fashion_men', '这件衬衫有几种颜色库存够吗', '亲，这款衬衫有白色、浅蓝、粉色、灰色四种颜色，都是经典百搭色。白色和浅蓝库存充足当天能发，粉色和灰色库存不多了预计2天内发货。您要是急用建议选白色或浅蓝。每个颜色我都拍了上身效果图，您可以看下选喜欢的颜色。支持退换，颜色不喜欢也可以换！已售上千件颜色反馈很好，放心拍。', '衬衫,颜色,库存,发货,百搭', '说明颜色库存情况并给发货建议', 85
  UNION ALL SELECT 'fashion_men', '这个价格能不能便宜点诚心要', '您好！这款已经是实在价了利润很薄。您要是诚心要我给您抹个零，再送您一双同品牌袜子。这个品质这个价格真的很良心了，您可以去比比看同款。咱们做生意靠回头客不坑人。您看行就拍不行我也不强求，交个朋友嘛。有什么需要随时联系我！已售上千件价格反馈很好。', '砍价,价格,赠品,诚意,成交', '适度让利加赠品促成交易', 87
  UNION ALL SELECT 'fashion_men', '夹克内衬是什么材质起球吗', '亲，这款夹克内衬是涤纶里布加了防静电处理，光滑不粘毛衣不起球不产生静电。穿脱方便不刮内衣。内衬做工也很好包边处理不会脱线。里布颜色是黑色耐脏好打理。已售400多件内衬反馈很好。有任何质量问题联系我们包退换，让您买得放心！细节经得起考验，放心拍。', '夹克,内衬,涤纶,防静电,不起球', '说明内衬材质及工艺特点', 84
  UNION ALL SELECT 'fashion_men', '卫衣厚度多少适合什么温度穿', '您好！这款卫衣分常规款和加绒款。常规款克重320g适合15到20度春秋穿，加绒款克重380g内里抓绒适合0到15度穿。您根据当地气温选就好。版型都是微宽松里面可以加衣服。两个款我都拍了细节图您可以对比下。支持退换尺码不合适可以换，邮费我们出！已售上千件厚度反馈很准。', '卫衣,厚度,温度,加绒,春秋', '说明不同厚度适用温度并引导选择', 86
  UNION ALL SELECT 'fashion_men', '西装尺码怎么选平时穿175的', '亲，西装尺码建议按胸围选最准。175身高标准身材选175码即44码，胸围108cm。要是您偏胖胸围超过110建议选大一号。西装讲究合身肩线刚好落在肩头，扣上扣子不紧不松。我把详细尺码表发您，您量下自己常穿西装的胸围肩围对比下。支持退换不合适可以换码！已售300多套尺码反馈很准。', '西装,尺码,胸围,合身,退换', '按胸围推荐西装尺码并引导测量', 87
  UNION ALL SELECT 'fashion_men', '衬衫是修身款还是宽松款偏瘦能穿吗', '您好！这款衬衫是修身版型，肩部和腰部做了收腰设计显身材。偏瘦身材穿正好显精神不显单薄。要是您偏胖建议选大一码或者看下我们的宽松款。修身款胸围比常规款小2到3cm。您把身高体重告诉我我帮您参考。支持退换尺码不合适包换邮费我们出！已售600多件版型反馈很好。', '衬衫,修身,版型,偏瘦,收腰', '说明版型适合身材并给选码建议', 85
  UNION ALL SELECT 'fashion_men', 'T恤领口会不会变大洗几次就松了', '亲，这款T恤领口用了1x1罗纹织法加双层加固，弹性好不易松垮。正常机洗几十次领口还是紧致有型。建议洗后领口整理好平铺晾干别用衣架挂着晾容易拉大。已售上千件领口反馈很好。要是洗后领口有松垮联系我们包退换，质量有保障！咱们做生意凭良心，每件都经过质检。', 'T恤,领口,罗纹,变形,洗涤', '说明领口工艺并给洗护建议', 84
  UNION ALL SELECT 'fashion_men', '外套拉链顺滑吗容易坏吗', '您好！这款外套用的是YKK拉链，顺滑不卡齿经久耐用。YKK是行业标杆品质拉链用几年都不会坏。拉链头金属质感很好拉起来手感顺滑。已售500多件拉链零投诉。要是拉链有任何问题联系我们免费换新，质量有保障。放心拍，细节经得起考验！咱们不拿次品忽悠人。', '外套,拉链,YKK,耐用,品质', '说明拉链品牌品质并承诺售后', 86
  UNION ALL SELECT 'fashion_men', '裤子面料是什么成分透气吗', '亲，这款裤子是98%棉加2%氨纶，棉质透气亲肤氨纶增加弹力。面料克重240g适中不厚不薄四季可穿。透气性很好夏天穿不闷热，弹力够活动方便不紧绷。已售800多条透气性反馈很好。建议冷水洗别暴晒。有任何问题联系我，包退换让您满意！咱们靠回头客做生意，质量有保障。', '裤子,面料,棉,透气,弹力', '说明面料成分及透气性能', 85
  UNION ALL SELECT 'fashion_men', '夹克能不能收腰有点显胖', '您好！这款夹克本身是微宽松版型，下摆有抽绳可以收紧收腰。您把抽绳拉紧打个结就有收腰效果了不显胖。要是您想要更修身的效果可以选小一码。夹克肩部也有设计不会显壮。我把上身效果图发您看下。支持退换要是不合适可以换码，邮费我们出！已售400多件版型反馈很好。', '夹克,收腰,版型,抽绳,显瘦', '提供收腰穿法并给选码建议', 84
  UNION ALL SELECT 'fashion_men', '这件衣服有瑕疵吗别收到才发现', '亲，全新带吊牌的，我发货前会逐件检查确保没有瑕疵。要是有线头我用剪刀修干净再发。您收到要是发现任何问题拍照给我立马退换邮费我出。做生意凭良心不会发有问题的货。已售上千件品质问题零投诉。放心拍，有任何问题随时联系处理！每件都经过质检才发货，让您买得放心。', '瑕疵,品质,检查,退换,吊牌', '承诺发货前检查并兜底退换', 89
  UNION ALL SELECT 'fashion_men', '发货快不快后天有事急着穿', '您好！今天下午4点前下单当天发，4点后第二天发。顺丰包邮一般2到3天到。您要是急我帮您备注加急，争取第二天到货。绝不耽误您的事。已售上千件发货速度反馈很好。您放心拍，今天下单明天大概率能到。有任何问题随时找我处理！咱们做事靠谱不忽悠人。', '发货,顺丰,加急,包邮,时效', '承诺当天发货并加急处理', 87
  UNION ALL SELECT 'fashion_men', '衬衫扣子结实吗容易掉吗', '亲，这款衬衫扣子是贝壳扣，用双线加固缝制不易脱落。正常穿着洗几十次扣子都不会掉。要是万一扣子松了或掉了您联系我免费补寄扣子。做工细节都很到位每颗扣子都检查过。已售600多件扣子问题零反馈。放心拍，质量有保障！咱们靠回头客做生意，细节经得起考验。', '衬衫,扣子,贝壳扣,加固,做工', '说明扣子品质并承诺售后', 83
  UNION ALL SELECT 'fashion_men', '这个款式过时吗穿出去会不会土', '您好！这是经典基础款不挑人不挑场合怎么搭都好看。基础款最不容易过时，今年穿明年穿都不过时。版型简洁大方上班休闲都能穿。我拍了上身效果和搭配建议图您可以看下。已售上千条好评率99%，款式反馈很好。放心入不会踩雷！有任何问题随时联系我处理。', '款式,基础款,百搭,经典,不过时', '说明款式经典性并引导搭配', 85
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 女装 fashion_women (30条) ============
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.51', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'fashion_women' AS code, '这条连衣裙160 100斤能穿吗' AS question, '亲，160身高100斤建议选S码哦~这款连衣裙S码胸围84cm腰围66cm裙长95cm，您身材标准的话S码正好。裙长95cm到膝盖上方显腿长。要是您喜欢宽松点可以选M码。连衣裙是高腰设计显腰细。支持7天退换尺码不合适包换邮费我们出，让您买得放心！已售上千件尺码反馈很准，有任何问题随时联系我。' AS answer, '连衣裙,尺码,身高体重,高腰,退换' AS tags, '根据身高体重推荐尺码并说明裙长' AS source_summary, 88 AS score
  UNION ALL SELECT 'fashion_women', '半身裙是什么材质的会皱吗', '您好！这款半身裙是100%聚酯纤维面料做了抗皱处理，不易起皱垂感好。正常穿着坐一天起来拍一拍就平整了。要是有些褶皱蒸汽熨一下就恢复。面料不粘毛不起球好打理。已售500多条抗皱性反馈很好。建议冷水洗别拧干自然晾干就好。有问题随时联系我包退换！咱们做生意凭良心不坑人。', '半身裙,材质,抗皱,聚酯纤维,垂感', '说明材质抗皱性能并给洗护建议', 86
  UNION ALL SELECT 'fashion_women', '衬衫是透的吗里面要不要穿打底', '亲，这款衬衫是雪纺面料有点微透，建议里面穿件浅色打底或吊带。白色会稍微透一点，浅蓝和黑色不透。雪纺面料轻薄透气夏天穿很舒服垂感也好。我穿了打底拍了个效果对比图您可以看下。已售800多件面料反馈很好。支持退换不满意可以换！有问题随时联系我处理。', '衬衫,雪纺,透,打底,透气', '说明面料透度并给穿搭建议', 85
  UNION ALL SELECT 'fashion_women', '外套搭配什么衣服好看', '您好！这款外套很百搭哦~可以搭连衣裙温柔风，搭牛仔裤T恤休闲风，搭半身裙知性风。我拍了三种搭配效果图您可以参考下。外套是短款显高显腿长，配高腰下装最好看。颜色是卡其色经典百搭不挑人。已售上千件搭配反馈很好。支持退换，搭配不满意可以换！有问题随时联系。', '外套,搭配,百搭,短款,显高', '提供多种搭配方案并引导参考效果图', 87
  UNION ALL SELECT 'fashion_women', '针织衫会不会起球怎么洗', '亲，这款针织衫是兔毛混纺面料柔软亲肤，正常穿着不易起球。要是摩擦多了局部可能有轻微起球用毛球修剪器处理就好。建议冷水手洗或放洗衣袋轻柔机洗，别拉扯别拧干平铺晾干。别暴晒别烘干。已售600多件起球反馈很少。有任何问题联系我包退换！咱们靠回头客做生意。', '针织衫,起球,兔毛,洗涤,手洗', '说明起球情况并给详细洗护建议', 86
  UNION ALL SELECT 'fashion_women', '连衣裙太长了能改短吗', '您好，连衣裙是可以改短的哦~建议拿到裁缝店改，改短10cm以内收费15到20块不影响版型。裙摆是A字型改短后比例还是协调的。要是您不想改也可以选小一码裙长会短2到3cm。您把身高告诉我我帮您参考选码。支持退换不合适可以换，邮费我们出！已售上千件改短反馈很好。', '连衣裙,改短,裙长,尺码,退换', '提供改短建议并帮助选码', 84
  UNION ALL SELECT 'fashion_women', '半身裙腰围太大怎么办我腰比较细', '亲，这款半身裙后腰有隐形拉链，腰围可以改小。您拿到裁缝店改小腰围收费10到15块。或者您选小一码，S码腰围64cm适合腰细的。裙子是A字版型腰围合适的话裙摆微张显胯小。您量下自己腰围对比下尺码表选合适的码。支持退换不合适可以换！已售500多条腰围反馈很准。', '半身裙,腰围,改小,A字,退换', '提供改腰建议并引导测量选码', 83
  UNION ALL SELECT 'fashion_women', '衬衫袖子多长能盖住手背吗', '您好！这款衬衫S码袖长56cm，M码57cm，L码58cm。正常袖长到虎口位置，不会盖住手背。要是您手臂长可以选大一码。袖口有扣子可以调节松紧。衬衫袖型是经典衬衫袖不紧不松活动方便。您量下自己常穿衬衫的袖长对比下更准。支持退换不合适可以换！已售800多件袖长反馈很准。', '衬衫,袖长,袖口,尺码,退换', '提供袖长数据并引导测量对比', 84
  UNION ALL SELECT 'fashion_women', '外套厚度多少冬天能穿吗', '亲，这款外套是薄款春秋外套，适合10到20度穿。冬天穿的话需要里面搭厚毛衣或者当内搭穿在大衣里面。要是您想冬天单穿可以看下我们的加厚款。薄款优点是不臃肿显利落，叠穿很百搭。我拍了厚度对比图您可以看下。支持退换要是不合适可以换！', '外套,厚度,冬季,叠穿,春秋', '说明厚度适用温度并给搭配建议', 85
  UNION ALL SELECT 'fashion_women', '针织衫会缩水吗洗了变小怎么办', '您好！这款针织衫做过预缩处理，冷水洗缩水率在3%以内基本看不出。建议冷水手洗别用热水别烘干，平铺晾干别挂晾容易拉长变形。要是万一洗缩水了联系我们包退换。兔毛混纺面料稳定性好正常洗护不会变形。已售600多件洗后反馈很好，放心入！', '针织衫,缩水,洗涤,预缩,保养', '说明预缩处理并给洗护建议', 85
  UNION ALL SELECT 'fashion_women', '连衣裙是什么版型显胖吗', '亲，这款连衣裙是A字高腰版型，收腰显腰细裙摆微张遮胯显瘦。不挑身材微胖也能穿。高腰线拉长腿部比例显高显腿长。V领设计修饰脸型显脸小领口不显胖。已售上千件显瘦反馈很好。我拍了不同身材上身效果图您可以看下。支持退换不合适可以换！', '连衣裙,版型,A字,显瘦,高腰', '说明版型显瘦设计并引导参考效果图', 89
  UNION ALL SELECT 'fashion_women', '半身裙怎么搭配上衣', '您好！这款半身裙很百搭哦~搭修身针织衫温柔知性，搭衬衫干练职场，搭T恤休闲日常。裙子是高腰款建议上衣扎进腰头显腰细显腿长。我拍了三种搭配效果图您可以参考。颜色是米色百搭不挑上衣颜色。已售500多条搭配反馈很好。支持退换搭配不满意可以换！', '半身裙,搭配,高腰,上衣,百搭', '提供多种搭配方案并引导参考', 86
  UNION ALL SELECT 'fashion_women', '衬衫领口是什么形状会不会显脸大', '亲，这款衬衫是V领设计，V领开口适中不会太低，修饰脸型显脸小显脖子长。比圆领更显瘦比方领更显柔和。领口有领托挺括有型不软塌。V领搭配项链也很好看。已售800多件领型反馈很好。我拍了领口细节图您可以看下。支持退换不合适可以换！', '衬衫,V领,领型,显脸小,修饰', '说明领型设计并引导参考细节图', 85
  UNION ALL SELECT 'fashion_women', '外套有内衬吗会不会透', '您好！这款外套有全内衬，涤纶里布光滑不粘衣服穿脱方便。有内衬不会透也不会扎皮肤。内衬做工很好包边处理不会脱线。里布颜色是黑色耐脏好打理。外套面料本身也有一定厚度不会透。已售400多件内衬反馈很好。有任何问题联系我包退换！', '外套,内衬,涤纶,不透,做工', '说明内衬工艺及不透特点', 84
  UNION ALL SELECT 'fashion_women', '针织衫什么颜色好看显白', '亲，这款针织衫有米白、燕麦、雾蓝、藕粉四种颜色。米白百搭不挑人显白，燕麦色温柔显气质，雾蓝显白显高级适合冷皮，藕粉显嫩显白适合暖皮。您可以根据自己肤色选。我拍了每种颜色上身效果图您可以对比下。已售600多件颜色反馈很好。支持退换颜色不喜欢可以换！', '针织衫,颜色,显白,肤色,百搭', '推荐适合肤色的颜色并引导参考效果图', 87
  UNION ALL SELECT 'fashion_women', '连衣裙面料是什么透气吗夏天穿热吗', '您好！这款连衣裙是100%聚酯纤维雪纺面料，轻薄透气垂感好夏天穿不热。面料有真丝般的光泽感但不娇气好打理。内里配了同色打底不会透。雪纺面料快干出差旅行好携带。已售上千件夏季爆款透气性反馈很好。建议冷水洗别暴晒。有问题随时联系！', '连衣裙,雪纺,透气,夏季,面料', '说明面料透气性能并给洗护建议', 88
  UNION ALL SELECT 'fashion_women', '半身裙长度到哪我155能穿吗', '亲，这款半身裙是中长款，S码裙长70cm到小腿肚位置。155身高穿S码裙长刚好到小腿不会压身高。高腰设计拉长比例反而显高。要是您想短一点可以选短款。我拍了155身高上身效果图您可以看下比例。支持退换尺码不合适可以换，邮费我们出！', '半身裙,裙长,身高,高腰,显高', '根据身高说明裙长比例并引导参考效果图', 86
  UNION ALL SELECT 'fashion_women', '衬衫扣子是什么材质的容易掉吗', '您好！这款衬衫扣子是珍珠扣，用双线加固缝制不易脱落。珍珠扣光泽感很好提升质感。正常穿着洗几十次扣子都不会掉。要是万一扣子松了或掉了联系我们免费补寄扣子。做工细节都很到位每颗扣子都检查过。已售800多件扣子问题零反馈。放心拍！', '衬衫,扣子,珍珠扣,加固,做工', '说明扣子材质品质并承诺售后', 83
  UNION ALL SELECT 'fashion_women', '外套是什么版型显瘦吗', '亲，这款外套是微宽松短款版型，不紧不松显瘦不臃肿。短款设计提高腰线显腿长。肩部微落肩不显肩宽。下摆微收显腰细。整体版型利落精神不显胖。已售500多件显瘦反馈很好。我拍了不同身材上身效果图您可以看下。支持退换不合适可以换！', '外套,版型,显瘦,短款,显高', '说明版型显瘦设计并引导参考效果图', 86
  UNION ALL SELECT 'fashion_women', '针织衫会不会扎人贴身穿舒服吗', '您好！这款针织衫是兔毛混纺面料，内里做了抓绒处理柔软亲肤不扎人，可以直接贴身穿。兔毛比普通羊毛更细更软保暖性也好。领口是圆领不勒脖子。已售600多件贴身穿反馈很好。要是您皮肤特别敏感建议里面穿件薄吊带。有任何不适联系我们包退换！', '针织衫,扎人,兔毛,亲肤,贴身', '说明面料亲肤性并给穿搭建议', 85
  UNION ALL SELECT 'fashion_women', '连衣裙洗涤要注意什么能机洗吗', '亲，这款连衣裙建议冷水手洗或放洗衣袋轻柔机洗。别用热水别漂白别拧干，自然晾干别暴晒。雪纺面料好打理但别和粗糙衣物混洗容易勾丝。洗后稍微整理下裙摆晾干垂感更好。要是裙子有褶皱蒸汽熨一下就平整。已售上千件洗后反馈很好。有问题联系我！', '连衣裙,洗涤,机洗,雪纺,保养', '给出详细洗护建议避免损坏', 85
  UNION ALL SELECT 'fashion_women', '半身裙面料起球吗怎么保养', '您好！这款半身裙面料做了抗起球处理，正常穿着不易起球。要是摩擦多了局部有轻微起球用毛球修剪器处理就好。建议冷水洗别暴晒别高温熨。裙子垂感好不需要经常熨，挂起来自然垂放就不皱。已售500多条保养反馈很好。有任何问题联系我包退换！', '半身裙,起球,保养,抗皱,垂感', '说明抗起球性能并给保养建议', 84
  UNION ALL SELECT 'fashion_women', '衬衫会不会透里面要穿什么', '亲，白色衬衫会有点微透建议里面穿件浅色内衣或吊带。浅蓝和黑色不透。衬衫面料是雪纺有一定垂感和光泽感，微透反而有层次感。我穿了打底拍了个效果对比图您可以看下。已售800多件面料反馈很好。支持退换要是不满意可以换。有问题随时联系！', '衬衫,透,内衣,雪纺,打底', '说明透度并给穿搭建议', 84
  UNION ALL SELECT 'fashion_women', '外套尺码怎么选160 105斤', '您好！160身高105斤建议选M码哦~这款外套M码胸围100cm衣长55cm。外套是微宽松版型里面可以加衣服。您要是喜欢修身效果选S码也可以。我把详细尺码表发您可以参考胸围肩宽数据。下单48小时内发货，试穿不满意支持退换邮费我们出！已售500多件尺码反馈很准。', '外套,尺码,身高体重,版型,退换', '根据身高体重推荐尺码并承诺退换', 86
  UNION ALL SELECT 'fashion_women', '针织衫版型是宽松还是修身', '亲，这款针织衫是微宽松版型，不紧不松显瘦不臃肿。肩部微落肩不显肩宽。下摆罗纹收口显腰细。版型不挑身材微胖也能穿。里面可以搭件薄打底冬天穿也OK。已售600多件版型反馈很好。我拍了不同身材上身效果图您可以看下。支持退换不合适可以换！', '针织衫,版型,宽松,显瘦,不挑身材', '说明版型特点并引导参考效果图', 85
  UNION ALL SELECT 'fashion_women', '连衣裙是拉链还是系带穿脱方便吗', '您好！这款连衣裙是后背隐形拉链，穿脱方便拉链顺滑不卡。隐形拉链不破坏裙子整体美感。拉链品质很好用几百次不会坏。裙子没有系带穿脱更方便。已售上千件拉链反馈很好。要是拉链有问题联系我们免费换新。放心拍，细节经得起考验！', '连衣裙,拉链,隐形拉链,穿脱,品质', '说明拉链设计及品质', 83
  UNION ALL SELECT 'fashion_women', '半身裙有口袋吗放手机方便吗', '亲，这款半身裙有两侧隐形口袋，可以放手机钥匙等小物件很方便。口袋是斜插设计不影响裙子版型不显胖。口袋布做了加固不会撕裂。已售500多条口袋反馈很实用。我拍了口袋细节图您可以看下。支持退换不合适可以换。有问题随时联系我！', '半身裙,口袋,隐形,实用,细节', '说明口袋设计及实用性', 83
  UNION ALL SELECT 'fashion_women', '衬衫多少钱能出便宜点呗', '您好！这款已经是实在价了面料做工都很好。您要是诚心要我给您抹个零再送您一条同品牌发圈。这个品质这个价格很良心了您可以比比看。咱们做生意靠回头客不坑人。您看行就拍不行也不强求交个朋友嘛。有什么需要随时联系我！', '砍价,价格,赠品,诚意,成交', '适度让利加赠品促成交易', 86
  UNION ALL SELECT 'fashion_women', '外套有几种颜色哪个好看', '亲，这款外套有卡其、黑色、米白三种颜色。卡其色经典百搭最热门，黑色显瘦显酷不挑人，米白温柔显气质。三种颜色都是基础色不挑搭配。我拍了每种颜色上身效果图您可以对比下。卡其色库存充足当天发，黑色和米白库存不多了。支持退换颜色不喜欢可以换！', '外套,颜色,百搭,库存,推荐', '推荐颜色并说明库存情况', 85
  UNION ALL SELECT 'fashion_women', '针织衫是正品吗支持验货吗', '您好！正品支持专柜验货假一赔十！您可以拿去专柜对比或者上得物鉴定，有问题全包退邮费我都出。吊牌洗标包装都是原厂的您收到一看就知道。我们做长久生意不干一锤子买卖。已售600多件正品问题零投诉。放心拍，有任何疑问随时找我！', '针织衫,正品,验货,假一赔十', '承诺正品验货并承担退换邮费', 90
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

-- ============ 鞋类 fashion_shoes (30条) ============
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.51', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'fashion_shoes' AS code, '这双运动鞋40码有吗我平时穿40' AS question, '亲，这款运动鞋40码有货哦~建议您选正码，平时穿40就选40。运动鞋版型标准不偏码。要是您脚宽或者脚背高可以选大半码。鞋内长25cm您量下自己脚长对比下更准。下单48小时内发货，试穿不合适支持退换邮费我们出。已售上千双码数反馈很准！' AS answer, '运动鞋,尺码,脚长,正码,退换' AS tags, '根据平时码数推荐并引导测量脚长' AS source_summary, 88 AS score
  UNION ALL SELECT 'fashion_shoes', '板鞋是什么材质的好打理吗', '您好！这款板鞋鞋面是头层牛皮的，耐穿有质感好打理。脏了用湿布擦一下就干净，不需要水洗。牛皮穿久了会有自然包浆更好看。鞋底是橡胶底耐磨防滑。已售800多双打理反馈很好。建议别泡水别暴晒。有任何问题联系我包退换！', '板鞋,材质,牛皮,打理,耐磨', '说明材质特点并给打理建议', 87
  UNION ALL SELECT 'fashion_shoes', '皮鞋版型偏码吗38码能穿吗', '亲，这款皮鞋版型标准不偏码，平时穿38就选38。皮鞋鞋面是真皮有延展性穿几天会更合脚。要是您脚宽可以选大半码。鞋内长24cm您量下脚长对比下。皮鞋新穿可能略紧穿几天就舒服了。支持退换尺码不合适可以换邮费我们出。已售500多双码数反馈很准！', '皮鞋,尺码,版型,真皮,退换', '说明版型特点并给选码建议', 86
  UNION ALL SELECT 'fashion_shoes', '拖鞋防滑吗浴室能穿吗', '您好！这款拖鞋鞋底是EVA材质，防滑纹路很深抓地力强，浴室穿完全没问题。鞋底厚1.5cm软硬适中走路舒服。鞋面是EVA一体成型防水好清洗。已售上千双防滑反馈很好。室内室外都能穿。建议别暴晒别接触高温容易变形。有问题联系我包退换！', '拖鞋,防滑,EVA,浴室,防水', '说明防滑性能及适用场景', 85
  UNION ALL SELECT 'fashion_shoes', '靴子是正品吗能验货吗', '亲，正品支持专柜验货假一赔十！您可以拿去专柜对比或者上得物鉴定，有问题全包退邮费我都出。吊牌鞋盒防伪卡都齐全您收到一看就知道。我们做长久生意不干一锤子买卖。已售500多双正品问题零投诉。放心拍，有任何疑问随时找我！', '靴子,正品,验货,假一赔十,鞋盒', '承诺正品验货并承担退换邮费', 92
  UNION ALL SELECT 'fashion_shoes', '运动鞋搭配什么裤子好看', '您好！这款运动鞋很百搭哦~搭运动裤休闲运动风，搭牛仔裤日常休闲，搭休闲裤轻快利落。鞋子是白色百搭不挑裤子颜色。低帮设计显腿长不压身高。我拍了三种搭配效果图您可以参考。已售上千双搭配反馈很好。支持退换搭配不满意可以换！', '运动鞋,搭配,百搭,低帮,显腿长', '提供多种搭配方案并引导参考', 87
  UNION ALL SELECT 'fashion_shoes', '板鞋鞋带是什么材质的容易断吗', '亲，这款板鞋鞋带是纯棉蜡芯鞋带，结实耐用不易断。蜡芯处理让鞋带不易松散不用频繁系。鞋带长度适中不会太长拖地。配色和鞋面搭配协调。已售800多双鞋带反馈很好。要是鞋带有问题联系我们免费补寄。放心拍，细节经得起考验！', '板鞋,鞋带,棉蜡芯,耐用,细节', '说明鞋带材质品质并承诺售后', 83
  UNION ALL SELECT 'fashion_shoes', '皮鞋怎么保养需要擦鞋油吗', '您好！皮鞋建议定期擦鞋油保养哦~穿3到4次擦一次鞋油，用无色鞋油就行。擦鞋油可以滋润皮革防开裂保持光泽。平时不穿放鞋撑防变形。别泡水别暴晒别连续穿让皮革休息。皮鞋保养好了穿好几年都不变形很划算。已售500多双保养反馈很好。有问题联系我！', '皮鞋,保养,鞋油,皮革,鞋撑', '给出详细保养建议延长寿命', 86
  UNION ALL SELECT 'fashion_shoes', '拖鞋尺码怎么选我穿38', '亲，拖鞋建议选正码，平时穿38就选38。拖鞋版型标准不偏码。拖鞋没有包裹略大半码也不影响穿着。鞋内长24cm您量下脚长对比下。EVA材质有弹力穿着舒适。已售上千双码数反馈很准。支持退换尺码不合适可以换邮费我们出。放心拍！', '拖鞋,尺码,正码,EVA,退换', '根据平时码数推荐并引导测量', 84
  UNION ALL SELECT 'fashion_shoes', '靴子筒高多少到小腿哪', '您好！这款靴子是及踝短靴，筒高15cm到脚踝上方。不挑腿型不显腿粗，小个子也能穿显高。筒围36cm适合大多数腿围。拉链在侧面穿脱方便。已售500多双筒高反馈很好。我拍了上身效果图您可以看下比例。支持退换不合适可以换！', '靴子,筒高,短靴,显高,筒围', '说明筒高及适合身材并引导参考效果图', 85
  UNION ALL SELECT 'fashion_shoes', '运动鞋是正品吗支持验货吗', '亲，正品支持专柜验货假一赔十！鞋盒防伪标二维码都可以验证。您可以拿去专柜对比或者扫码验证，有问题全包退邮费我都出。我们做长久生意不干一锤子买卖。已售上千双正品问题零投诉。放心拍，有任何疑问随时找我处理！', '运动鞋,正品,验货,防伪,假一赔十', '承诺正品验货并说明验证方式', 91
  UNION ALL SELECT 'fashion_shoes', '板鞋尺码偏大还是偏小', '您好！这款板鞋版型标准不偏码，平时穿多少码就选多少码。要是您脚宽或者脚背高建议选大半码。鞋内长数据我发您，您量下脚长对比下更准。板鞋鞋面是牛皮有延展性穿几天会更合脚。支持退换尺码不合适可以换邮费我们出。已售800多双码数反馈很准！', '板鞋,尺码,偏码,脚宽,退换', '说明版型不偏码并给选码建议', 85
  UNION ALL SELECT 'fashion_shoes', '皮鞋鞋面是什么皮真皮吗', '亲，这款皮鞋鞋面是头层牛皮的，真皮有毛孔会呼吸穿着不闷脚。头层牛皮比二层皮更耐用更有质感。您收到可以按一下鞋面有细小皱纹松开恢复就是真皮。牛皮穿久了会有自然包浆更好看。已售500多双材质反馈很好。有任何质量问题联系我包退换！', '皮鞋,鞋面,头层牛皮,真皮,透气', '说明真皮材质及辨别方法', 88
  UNION ALL SELECT 'fashion_shoes', '拖鞋底厚吗走路舒服吗', '您好！这款拖鞋鞋底厚1.5cm，EVA材质软硬适中走路很舒服。鞋底有防滑纹路抓地力强。鞋面宽度适中不挤脚。EVA材质很轻穿一天不累脚。已售上千双舒适度反馈很好。室内穿室外穿都OK。有问题联系我包退换，让您买得放心！', '拖鞋,鞋底,EVA,舒适,防滑', '说明鞋底厚度及舒适度', 84
  UNION ALL SELECT 'fashion_shoes', '靴子内衬是什么材质保暖吗', '亲，这款靴子内衬是短毛绒，保暖性好0度以上穿完全OK。毛绒亲肤不扎可以直接穿薄袜子。内衬做工很好不掉毛不起球。靴筒有拉链穿脱方便不用解鞋带。已售500多双保暖反馈很好。要是您那边零下可以搭厚袜子。支持退换不合适可以换！', '靴子,内衬,毛绒,保暖,拉链', '说明内衬保暖性能并给穿搭建议', 86
  UNION ALL SELECT 'fashion_shoes', '运动鞋鞋底软吗跑步舒服吗', '您好！这款运动鞋鞋底是EVA发泡加橡胶贴片，软弹适中走路跑步都很舒服。前掌有弯曲槽弯折方便。后跟有缓震设计减震保护膝盖。鞋底耐磨橡胶贴片提升了耐用性。已售上千双舒适度反馈很好。日常通勤轻运动完全够用。支持退换不合适可以换！', '运动鞋,鞋底,EVA,缓震,舒适', '说明鞋底科技及舒适度', 88
  UNION ALL SELECT 'fashion_shoes', '板鞋耐磨吗能穿多久', '亲，这款板鞋鞋底是橡胶底，耐磨性好正常穿大半年没问题。鞋面头层牛皮耐穿耐看越穿越有质感。鞋底纹路深抓地力强不易磨平。已售800多双耐磨反馈很好。建议别连续穿让鞋子休息延长寿命。有问题联系我包退换。放心拍，质量有保障！', '板鞋,耐磨,橡胶底,牛皮,寿命', '说明耐磨性能并给延长寿命建议', 85
  UNION ALL SELECT 'fashion_shoes', '皮鞋穿久了会变形吗', '您好！皮鞋穿久了会有些变形但可以保养恢复。建议不穿时放鞋撑撑住鞋型。别连续穿让皮革休息恢复弹性。穿3到4次擦次鞋油滋润皮革防开裂。别泡水别暴晒。皮鞋保养好了穿好几年都不变形很划算。已售500多双保养反馈很好。有问题联系我！', '皮鞋,变形,鞋撑,保养,皮革', '说明保养方法防止变形', 85
  UNION ALL SELECT 'fashion_shoes', '拖鞋有几种颜色哪个好看', '亲，这款拖鞋有白色、黑色、米色、灰色四种颜色。白色清爽百搭最热门，黑色显瘦耐脏不挑人，米色温柔显气质，灰色高级有质感。四种都是基础色不挑搭配。我拍了每种颜色实物图您可以对比下。白色库存充足当天发，其他颜色库存不多了。支持退换颜色不喜欢可以换！', '拖鞋,颜色,百搭,库存,推荐', '推荐颜色并说明库存情况', 84
  UNION ALL SELECT 'fashion_shoes', '靴子拉链顺滑吗容易坏吗', '您好！这款靴子用的是YKK拉链，顺滑不卡齿经久耐用。YKK是行业标杆品质用几年都不会坏。拉链在侧面穿脱方便不用使劲拽。已售500多双拉链零投诉。要是拉链有问题联系我们免费换新，质量有保障。放心拍，细节经得起考验！', '靴子,拉链,YKK,耐用,品质', '说明拉链品牌品质并承诺售后', 86
  UNION ALL SELECT 'fashion_shoes', '运动鞋透气吗夏天穿热吗', '亲，这款运动鞋鞋面是飞织面料透气性很好，夏天穿不闷脚。鞋面有网孔散热快。鞋垫也是透气材质不闷汗。飞织面料轻便包裹性好。已售上千双透气性反馈很好。夏天穿完全OK。要是您脚容易出汗可以搭透气运动袜。支持退换不合适可以换！', '运动鞋,透气,飞织,夏季,网孔', '说明透气性能并给穿搭建议', 87
  UNION ALL SELECT 'fashion_shoes', '板鞋能水洗吗脏了怎么清理', '您好！板鞋不建议整体水洗容易脱胶。鞋面脏了用湿布蘸点清洁剂擦一下就干净。鞋底用刷子刷一下就好。别泡水别暴晒别烘干自然晾干。鞋内可以放除味包保持清新。已售800多双打理反馈很好。有任何问题联系我包退换。放心拍！', '板鞋,清洗,水洗,打理,保养', '给出清理建议避免损坏', 84
  UNION ALL SELECT 'fashion_shoes', '皮鞋尺码偏大还是偏小我脚窄', '亲，这款皮鞋版型标准不偏码，平时穿多少码就选多少码。脚窄的话选正码正好，皮鞋有系带可以调节松紧。要是您脚宽可以选大半码。鞋内长数据我发您量下脚长对比下。真皮有延展性穿几天会更合脚。支持退换尺码不合适可以换邮费我们出！', '皮鞋,尺码,脚窄,系带,退换', '根据脚型推荐尺码并引导测量', 85
  UNION ALL SELECT 'fashion_shoes', '拖鞋底会打滑吗瓷砖地面能穿吗', '您好！这款拖鞋鞋底有深纹路防滑设计，瓷砖地面穿完全没问题不打滑。EVA材质本身也有一定摩擦力。浴室厨房瓷砖地面都能穿。已售上千双防滑反馈很好。要是地面有水还是注意一下安全。有问题联系我包退换，让您买得放心！', '拖鞋,防滑,瓷砖,EVA,安全', '说明防滑性能及适用地面', 83
  UNION ALL SELECT 'fashion_shoes', '靴子尺码怎么选平时穿38', '亲，靴子建议选正码，平时穿38就选38。靴子版型标准不偏码。冬天穿可以选大半码里面搭厚袜子。鞋内长24cm您量下脚长对比下。靴筒有拉链穿脱方便。已售500多双码数反馈很准。支持退换尺码不合适可以换邮费我们出。放心拍！', '靴子,尺码,正码,冬天,退换', '根据平时码数推荐并给冬季选码建议', 85
  UNION ALL SELECT 'fashion_shoes', '运动鞋有几种颜色哪个好看', '您好！这款运动鞋有全白、黑白、全黑三种配色。全白最百搭最热门清爽干净，黑白配色经典有层次，全黑显瘦显酷耐脏。三种都是经典配色不挑衣服。我拍了每种配色实物图您可以对比下。全白库存充足当天发其他配色库存不多了。支持退换颜色不满意可以换！', '运动鞋,颜色,配色,百搭,库存', '推荐配色并说明库存情况', 86
  UNION ALL SELECT 'fashion_shoes', '板鞋款式过时吗穿出去会不会土', '亲，这款板鞋是经典帆布板鞋款式，简洁大方不挑人不挑场合，今年穿明年穿都不过时。低帮设计显腿长百搭各种裤子。板鞋是永远不会过时的鞋款，比运动鞋更日常比皮鞋更休闲。已售800多双款式反馈很好。放心入不会踩雷。支持退换不满意可以换！', '板鞋,款式,经典,百搭,不过时', '说明款式经典性并引导选择', 85
  UNION ALL SELECT 'fashion_shoes', '皮鞋搭配什么裤子好看', '您好！这款皮鞋很百搭哦~搭西裤商务正式，搭牛仔裤休闲，搭休闲裤日常通勤。皮鞋是德比鞋款不挑场合。黑色最百搭不挑裤子颜色。我拍了三种搭配效果图您可以参考。已售500多双搭配反馈很好。支持退换搭配不满意可以换！', '皮鞋,搭配,德比,百搭,商务', '提供多种搭配方案并引导参考', 86
  UNION ALL SELECT 'fashion_shoes', '拖鞋能外穿吗出门会不会奇怪', '亲，这款拖鞋是一字拖款式设计简洁大方，出门穿完全不会奇怪。很多男生夏天外穿这种拖鞋很潮很休闲。鞋面宽度适中不显廉价。搭短裤休闲裤都好看。已售上千双外穿反馈很好。室内穿室外穿都OK。有问题联系我包退换。放心拍！', '拖鞋,外穿,一字拖,休闲,搭配', '说明外穿可行性并给搭配建议', 83
  UNION ALL SELECT 'fashion_shoes', '靴子冬天穿够暖吗零下能穿吗', '您好！这款靴子内衬短毛绒保暖性好，0度以上穿完全OK。零下10度可以搭厚羊毛袜子也够暖。零下10度以下建议选加绒款。靴筒及踝不挑身材显高。皮面防风挡寒。已售500多双保暖反馈很好。您根据当地气温选就好。支持退换不合适可以换！', '靴子,保暖,冬季,毛绒,加绒', '说明保暖性能并给适用温度建议', 87
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

