       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.51', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'fashion_bags' AS code, '这个背包容量多大能装电脑吗' AS question, '亲，这款背包容量25L，有独立电脑隔层最大可装15.6寸笔记本。还有平板隔层和多个小口袋分类收纳。主袋空间很大可以装书本衣服水杯雨伞。背包适合通勤上学出差旅行。已售上千个容量反馈很实用。支持退换不满意可以换。有问题随时联系！' AS answer, '背包,容量,电脑,通勤,收纳' AS tags, '说明容量及收纳设计' AS source_summary, 88 AS score
  UNION ALL SELECT 'fashion_bags', '手提包是什么材质的真皮吗', '您好！这款手提包是头层牛皮的，真皮有质感耐用越用越好看。您收到可以按一下皮面有细小皱纹松开恢复就是真皮。牛皮手感柔软有光泽。包内里布是涤纶光滑不粘东西。五金是合金电镀不易掉色。已售500多个材质反馈很好。有任何问题联系我包退换！', '手提包,材质,头层牛皮,真皮,五金', '说明真皮材质及辨别方法', 89
  UNION ALL SELECT 'fashion_bags', '钱包是正品吗能验货吗', '亲，正品支持专柜验货假一赔十！防伪卡吊牌包装都齐全您可以验证。有问题全包退邮费我都出。我们做长久生意不干一锤子买卖。已售800多个正品问题零投诉。放心拍，有任何疑问随时找我。钱包细节都很到位经得起检验！', '钱包,正品,验货,假一赔十,防伪', '承诺正品验货并承担退换邮费', 91
  UNION ALL SELECT 'fashion_bags', '行李箱20寸能带上飞机吗', '您好！这款20寸行李箱尺寸是55x35x20cm，符合大多数航空公司登机箱标准，可以随身带上飞机不用托运。建议您出行前确认下航司尺寸要求。箱子是PC材质轻便耐摔。四个万向轮顺滑静音。已售上千个出行反馈很好。支持退换不合适可以换。有问题联系我！', '行李箱,20寸,登机,飞机,PC', '说明登机可行性及材质特点', 88
  UNION ALL SELECT 'fashion_bags', '托特包容量多大能装什么', '亲，这款托特包容量很大，可以装A4文件夹笔记本电脑水杯雨伞化妆包等。包口是磁扣开合拿取方便。包内有个小拉链袋放贵重物品。托特包适合通勤购物逛街旅行。已售600多个容量反馈很实用。支持退换不满意可以换。有问题随时联系我！', '托特包,容量,通勤,收纳,磁扣', '说明容量及适用场景', 86
  UNION ALL SELECT 'fashion_bags', '背包防水吗下雨天能背吗', '您好！这款背包面料做了防泼水处理，小雨毛毛雨完全没问题水珠会滑落。但大雨暴雨不建议长时间淋。面料本身是尼龙耐磨耐用。拉链也做了防水处理。已售上千个防水反馈很好。日常通勤遇雨完全OK。有问题联系我包退换。放心拍！', '背包,防水,防泼水,尼龙,通勤', '说明防水等级及适用场景', 85
  UNION ALL SELECT 'fashion_bags', '手提包尺码多大能装什么', '亲，这款手提包尺寸是30x20x12cm，可以装手机钱包钥匙化妆品纸巾雨伞等日常用品。包内空间设计合理分层收纳方便找东西。包口是拉链开合安全防盗。手提和单肩两种背法。已售500多个容量反馈很实用。支持退换不合适可以换。有问题联系我！', '手提包,尺寸,容量,背法,收纳', '说明尺寸及容量实用性', 84
  UNION ALL SELECT 'fashion_bags', '钱包容量多大能装几张卡', '您好！这款钱包有8个卡位可以装8张卡，2个钞票位可以装现金，1个拉链袋可以装硬币和小物件。钱包尺寸10x9cm小巧便携可以放口袋。真皮材质耐用有质感。已售800多个容量反馈很实用。支持退换不合适可以换。有问题联系我包退换！', '钱包,容量,卡位,尺寸,真皮', '说明容量及卡位设计', 85
  UNION ALL SELECT 'fashion_bags', '行李箱轮子顺滑吗静音吗', '亲，这款行李箱用的是万向静音轮，顺滑不卡顿噪音很小。轮子是橡胶材质耐磨减震。四个轮子360度旋转推拉省力。已售上千个轮子反馈很好。拉杆是铝合金四档可调适合不同身高。支持退换不合适可以换。有问题联系我。放心拍！', '行李箱,轮子,万向轮,静音,拉杆', '说明轮子品质及拉杆设计', 87
  UNION ALL SELECT 'fashion_bags', '托特包是什么材质的耐用吗', '您好！这款托特包是帆布面料，耐磨耐用承重性好。帆布面料做了防水处理不怕小雨。包底有加固缝线不易开裂。五金是合金电镀不易掉色。已售600多个耐用反馈很好。帆布包越用越有质感很耐操。建议别长时间暴晒。有问题联系我包退换！', '托特包,材质,帆布,耐用,防水', '说明材质及耐用性能', 85
  UNION ALL SELECT 'fashion_bags', '背包肩带舒服吗会不会勒肩膀', '亲，这款背包肩带是S型减压设计，里面填充了海绵，背起来很舒服不会勒肩膀。肩带可以调节长度适合不同身高。背包有胸带可以分担重量，长时间背也不累。背部还有透气网垫散热不闷汗。已售上千个舒适度反馈很好。支持退换不合适可以换。有问题随时联系我！', '背包,肩带,减压,舒适,调节', '说明肩带设计及舒适度', 86
  UNION ALL SELECT 'fashion_bags', '手提包五金是什么材质会掉色吗', '您好！这款手提包五金是合金电镀材质，不易掉色不易生锈。五金做了抗氧化处理日常使用能保持光泽。您收到可以用干布擦拭保养。五金颜色是银色百搭不挑衣服。已售500多个五金反馈很好。要是有掉色问题联系我们包退换。放心拍，细节经得起考验！', '手提包,五金,合金,电镀,不掉色', '说明五金材质及保养建议', 84
  UNION ALL SELECT 'fashion_bags', '钱包是什么颜色百搭吗', '亲，这款钱包有黑色和棕色两种颜色。黑色经典百搭最热门不挑人，棕色商务有质感显品味。两个颜色都是基础色怎么搭都好看。我拍了每种颜色实物图您可以对比下。已售800多个颜色反馈很好。支持退换颜色不喜欢可以换。有问题随时联系我！', '钱包,颜色,百搭,黑色,棕色', '推荐颜色并说明百搭性', 83
  UNION ALL SELECT 'fashion_bags', '行李箱拉杆结实吗会晃吗', '您好！这款行李箱拉杆是铝合金材质，结实耐用不晃动。拉杆四档可调适合不同身高。拉杆做了加厚处理承重性好可以挂重物。拉杆顺滑伸缩不卡顿。已售上千个拉杆反馈很好。要是有问题联系我们包退换。放心拍，质量有保障！', '行李箱,拉杆,铝合金,结实,可调', '说明拉杆材质及品质', 86
  UNION ALL SELECT 'fashion_bags', '托特包有几种颜色哪个好看', '亲，这款托特包有黑色、米白、卡其三种颜色。黑色经典百搭最耐脏，米白温柔显气质适合女生，卡其文艺有质感男女都能用。三个颜色都是基础色不挑搭配。我拍了每种颜色实物图您可以对比下。黑色库存充足当天发，其他颜色库存不多了。支持退换颜色不喜欢可以换！', '托特包,颜色,百搭,库存,推荐', '推荐颜色并说明库存情况', 85
  UNION ALL SELECT 'fashion_bags', '背包有几个颜色哪个好看', '您好！这款背包有黑色、深蓝、灰色三种颜色。黑色经典百搭最热门不挑人，深蓝商务有质感适合通勤，灰色时尚显年轻。三个颜色都是基础色不挑衣服。我拍了每种颜色实物图您可以对比下。黑色库存充足当天发，深蓝和灰色库存不多了。支持退换颜色不满意可以换！', '背包,颜色,百搭,库存,推荐', '推荐颜色并说明库存情况', 85
  UNION ALL SELECT 'fashion_bags', '手提包能斜挎吗有肩带吗', '亲，这款手提包配有可拆卸肩带，可以手提、单肩、斜挎三种背法。肩带长度可以调节适合不同身高。肩带和包身连接处用了五金扣环结实耐用。已售500多个背法反馈很好。三种背法适应不同场合很实用。支持退换不合适可以换。有问题随时联系我！', '手提包,斜挎,肩带,背法,可拆卸', '说明背法多样性及实用性', 86
  UNION ALL SELECT 'fashion_bags', '钱包是什么款式长款短款', '您好！这款钱包是短款折叠式，尺寸10x9cm小巧便携可以放口袋。短款比长款更轻便出门不累赘。打开后有8个卡位2个钞票位1个拉链袋，容量完全够日常使用。已售800多个款式反馈很好。要是有问题联系我包退换。放心拍，实用又便携！', '钱包,款式,短款,便携,容量', '说明款式特点及便携性', 84
  UNION ALL SELECT 'fashion_bags', '行李箱密码锁怎么设置安全吗', '亲，这款行李箱配的是TSA密码锁，出国托运海关可以用专用钥匙开锁不会撬坏箱子。密码锁初始密码是000，您可以按旁边小按钮设置自己的密码。TSA锁比普通锁更安全更方便。已售上千个密码锁反馈很好。要是有问题联系我包退换。放心拍，出行更安心！', '行李箱,密码锁,TSA,安全,设置', '说明密码锁类型及设置方法', 86
  UNION ALL SELECT 'fashion_bags', '托特包能装电脑吗有隔层吗', '您好！这款托特包内有电脑隔层可以装13到15寸笔记本，隔层有魔术贴固定电脑不会晃动。还有平板隔层和几个小口袋分类收纳。主袋空间很大可以装文件书本水杯等。已售600多个容量反馈很实用。支持退换不合适可以换。有问题随时联系我！', '托特包,电脑,隔层,容量,收纳', '说明电脑隔层设计及容量', 85
  UNION ALL SELECT 'fashion_bags', '背包是什么款式商务还是休闲', '亲，这款背包是商务休闲两用款式，简洁大方的设计上班通勤商务场合都能用，周末出行休闲场合也不违和。背包颜色是黑色百搭不挑衣服。容量大功能多适合多种场景。已售上千个款式反馈很好。支持退换不合适可以换。有问题随时联系我处理！', '背包,款式,商务,休闲,百搭', '说明款式适用场景', 84
  UNION ALL SELECT 'fashion_bags', '手提包拉链顺滑吗容易坏吗', '您好！这款手提包用的是YKK拉链，顺滑不卡齿经久耐用。YKK是行业标杆品质拉链用几年都不会坏。拉链头金属质感很好拉起来手感顺滑。包口拉链开合安全防盗。已售500多个拉链零投诉。要是拉链有问题联系我们免费换新，质量有保障。放心拍！', '手提包,拉链,YKK,耐用,品质', '说明拉链品牌品质并承诺售后', 85
  UNION ALL SELECT 'fashion_bags', '钱包耐用吗能用多久', '亲，这款钱包是头层牛皮的，真皮耐用用几年没问题。牛皮越用越有质感越用越柔软。缝线是高强线加固不易断。五金做了抗氧化处理不易掉色。已售800多个耐用反馈很好。正常使用一个钱包用好几年很划算。有任何问题联系我包退换。放心拍！', '钱包,耐用,真皮,寿命,牛皮', '说明耐用性能及使用寿命', 85
  UNION ALL SELECT 'fashion_bags', '行李箱耐摔吗托运会不会坏', '您好！这款行李箱是PC材质，柔韧耐摔轻便。PC材质比ABS更有弹性受到冲击会回弹不易开裂。箱子角部做了加厚加固处理最耐摔的位置。托运建议套个保护套防止刮花。已售上千个托运反馈很好。要是有问题联系我包退换。放心拍，质量有保障！', '行李箱,耐摔,PC,托运,加固', '说明耐摔性能并给托运建议', 86
  UNION ALL SELECT 'fashion_bags', '托特包肩带舒服吗会不会勒肩膀', '亲，这款托特包肩带是宽肩带设计，宽度4cm受力面积大不勒肩膀。肩带做了加厚填充背起来很舒服。肩带长度可以调节适合不同身高。肩带和包身连接处用了五金扣环加固结实耐用。已售600多个舒适度反馈很好。支持退换不合适可以换。有问题联系我！', '托特包,肩带,宽肩带,舒适,加固', '说明肩带设计及舒适度', 84
  UNION ALL SELECT 'fashion_bags', '背包多少钱能便宜点吗', '您好！这款已经是实在价了利润很薄。您要是诚心要我给您抹个零再送您一个同品牌收纳袋。这个品质这个价格真的很良心了您可以比比看同款。咱们做生意靠回头客不坑人。您看行就拍不行也不强求交个朋友嘛。有什么需要随时联系我！已售上千个价格反馈很好。', '砍价,价格,赠品,诚意,成交', '适度让利加赠品促成交易', 85
  UNION ALL SELECT 'fashion_bags', '手提包是正品吗支持验货吗', '亲，正品支持专柜验货假一赔十！防伪卡吊牌包装都齐全您可以验证。有问题全包退邮费我都出。我们做长久生意不干一锤子买卖。已售500多个正品问题零投诉。放心拍，有任何疑问随时找我。手提包细节都很到位经得起检验！', '手提包,正品,验货,假一赔十,防伪', '承诺正品验货并承担退换邮费', 90
  UNION ALL SELECT 'fashion_bags', '钱包有几种颜色哪个好看', '您好！这款钱包有黑色、棕色、酒红三种颜色。黑色经典百搭最热门不挑人，棕色商务有质感显品味，酒红时尚有个性显气质。三个颜色都是基础色不挑搭配。我拍了每种颜色实物图您可以对比下。黑色库存充足当天发，其他颜色库存不多了。支持退换颜色不满意可以换！', '钱包,颜色,百搭,库存,推荐', '推荐颜色并说明库存情况', 84
  UNION ALL SELECT 'fashion_bags', '行李箱容量多大能装多少', '亲，这款20寸行李箱容量38L，可以装3到5天的衣物。24寸容量60L可以装5到7天的衣物。28寸容量85L可以装7到10天的衣物适合长途旅行。箱内有交叉绑带固定衣物和拉链隔层分区收纳。已售上千个容量反馈很实用。支持退换不合适可以换。有问题联系我！', '行李箱,容量,收纳,旅行,尺寸', '说明不同尺寸容量及适用场景', 87
  UNION ALL SELECT 'fashion_bags', '托特包脏了怎么清理能洗吗', '您好！托特包建议别整体水洗容易变形。局部脏了用湿布蘸点中性清洁剂擦一下就干净。别用漂白剂别暴晒别烘干自然晾干就好。帆布面料耐操好打理。要是不小心弄脏了及时清理别等污渍渗入。已售600多个打理反馈很好。有任何问题联系我包退换。放心拍！', '托特包,清理,清洗,保养,帆布', '给出清理建议避免损坏', 83
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;

