INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.51', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'fashion_accessories' AS code, '帽子尺码多大头围多少能戴' AS question, '亲，这款帽子是均码可调节设计，头围54到60cm都能戴。帽子后边有调节扣可以调大小，头大头小都能找到合适的尺寸。帽檐宽度7cm防晒效果好。帽子材质是棉布透气不闷热。已售上千顶尺码反馈很好。支持退换不合适可以换。有问题随时联系我处理！' AS answer, '帽子,尺码,头围,可调节,防晒' AS tags, '说明尺码可调节性及头围范围' AS source_summary, 87 AS score
  UNION ALL SELECT 'fashion_accessories', '围巾是什么材质的会扎人吗', '您好！这款围巾是100%聚酯纤维仿羊绒面料，柔软亲肤不扎人，手感像真羊绒一样软糯。仿羊绒比真羊绒更好打理不易起球不易变形。围巾做了加厚处理保暖性好。已售800多条材质反馈很好。建议冷水洗别暴晒。有任何问题联系我包退换！咱们靠回头客做生意。', '围巾,材质,仿羊绒,不扎人,保暖', '说明材质亲肤性并给洗护建议', 88
  UNION ALL SELECT 'fashion_accessories', '手表是正品吗能验货吗', '亲，正品支持专柜验货假一赔十！您可以拿去专柜对比或者扫码验证防伪，有问题全包退邮费我都出。我们做长久生意不干一锤子买卖。吊牌保修卡包装都齐全您收到一看就知道。已售500多块正品问题零投诉。放心拍，有任何疑问随时找我处理！', '手表,正品,验货,假一赔十,防伪', '承诺正品验货并承担退换邮费', 92
  UNION ALL SELECT 'fashion_accessories', '项链是什么材质会掉色吗', '您好！这款项链是S925银镀金的，不易掉色不易过敏。S925银是国际标准银饰材质，亲肤性好不过敏。镀金层做了加固处理日常佩戴能保持光泽。建议别接触化学品别泡温泉。已售600多条材质反馈很好。要是有掉色问题联系我们包退换。放心拍！', '项链,材质,S925银,镀金,不掉色', '说明材质及保养建议', 87
  UNION ALL SELECT 'fashion_accessories', '墨镜防紫外线吗开车能戴吗', '亲，这款墨镜是UV400防紫外线的，可以过滤99%的紫外线，开车完全可以戴。镜片是偏光镜片能消除眩光，开车视野更清晰更安全。镜片颜色是灰色不偏色，看红绿灯也清楚。已售上千副防紫外线反馈很好。支持退换不合适可以换。有问题随时联系我！', '墨镜,防紫外线,偏光,开车,UV400', '说明防紫外线性能及开车适用性', 89
  UNION ALL SELECT 'fashion_accessories', '帽子是什么材质的防晒吗', '您好！这款帽子是棉布面料，UPF50+防晒指数可以阻挡98%的紫外线。帽檐宽度7cm足够遮住脸部和脖子。棉布透气不闷热夏天戴很舒服。帽子有透气孔散热更好。已售上千顶防晒反馈很好。支持退换不合适可以换。有问题随时联系我处理！', '帽子,材质,棉布,防晒,UPF50', '说明防晒性能及材质特点', 88
  UNION ALL SELECT 'fashion_accessories', '围巾多大怎么搭配好看', '亲，这款围巾尺寸是180x70cm，可以绕一圈也可以绕两圈。绕一圈休闲随意，绕两圈保暖显层次。颜色是米色百搭不挑衣服。搭大衣优雅知性，搭羽绒服温暖实用，搭西装干练有型。我拍了三种搭配效果图您可以参考。已售800多条搭配反馈很好。支持退换搭配不满意可以换！', '围巾,搭配,尺寸,百搭,绕法', '说明尺寸并提供多种搭配方案', 86
  UNION ALL SELECT 'fashion_accessories', '手表防水吗洗手能戴吗', '您好！这款手表是3ATM生活防水，洗手溅水完全没问题不用摘下。但别戴着洗澡游泳，热水和蒸汽会损坏防水圈。防水圈建议每1到2年更换一次保持防水性能。已售500多块防水反馈很好。要是有进水问题联系我们包退换。放心拍，日常使用完全OK！', '手表,防水,3ATM,洗手,生活防水', '说明防水等级及使用注意事项', 85
  UNION ALL SELECT 'fashion_accessories', '项链多长到哪个位置', '亲，这款项链长度是45cm，可以调节到42cm。45cm到锁骨下方刚好显锁骨好看，42cm到锁骨位置更精致。这个长度是最百搭的锁骨链长度，搭各种领口都好看。已售600多条长度反馈很好。我拍了佩戴效果图您可以看下位置。支持退换不合适可以换！', '项链,长度,锁骨链,调节,百搭', '说明项链长度及佩戴位置', 84
  UNION ALL SELECT 'fashion_accessories', '墨镜是什么款式适合什么脸型', '您好！这款墨镜是飞行员款式，经典百搭不挑脸型。圆脸戴显脸小显立体，方脸戴柔和脸部线条，椭圆脸戴更显气质。镜框是金属框轻薄有质感。我拍了不同脸型佩戴效果图您可以参考。已售上千副款式反馈很好。支持退换不合适可以换。有问题联系我！', '墨镜,款式,飞行员,脸型,百搭', '说明款式并推荐适合脸型', 86
  UNION ALL SELECT 'fashion_accessories', '帽子有几种颜色哪个好看', '亲，这款帽子有黑色、米白、卡其三种颜色。黑色经典百搭最耐脏不挑人，米白清爽显气质适合女生，卡其文艺有质感男女都能用。三个颜色都是基础色不挑搭配。我拍了每种颜色实物图您可以对比下。黑色库存充足当天发，其他颜色库存不多了。支持退换颜色不满意可以换！', '帽子,颜色,百搭,库存,推荐', '推荐颜色并说明库存情况', 84
  UNION ALL SELECT 'fashion_accessories', '围巾会不会起球怎么洗', '您好！这款围巾是仿羊绒面料做了抗起球处理，正常佩戴不易起球。要是摩擦多了局部有轻微起球用毛球修剪器处理就好。建议冷水手洗或放洗衣袋轻柔机洗，别拧干平铺晾干别暴晒。别和粗糙衣物混洗。已售800多条洗后反馈很好。有任何问题联系我包退换！', '围巾,起球,洗涤,仿羊绒,保养', '说明抗起球性能并给洗护建议', 85
  UNION ALL SELECT 'fashion_accessories', '手表表带是什么材质舒服吗', '亲，这款手表表带是不锈钢的，做了抛光处理光泽感很好。不锈钢表带耐用不易过敏亲肤性好。表带可以拆卸调节数量适合不同手腕。表带宽度20mm贴合手腕佩戴舒服。已售500多块表带反馈很好。要是有问题联系我包退换。放心拍，细节经得起考验！', '手表,表带,不锈钢,舒服,调节', '说明表带材质及舒适度', 85
  UNION ALL SELECT 'fashion_accessories', '项链搭配什么衣服好看', '您好！这款锁骨链很百搭哦~搭V领显锁骨好看，搭圆领增添精致感，搭衬衫知性优雅。项链是简约款式不挑衣服颜色。叠搭其他项链也好看很有层次感。我拍了三种搭配效果图您可以参考。已售600多条搭配反馈很好。支持退换搭配不满意可以换！有问题随时联系我。', '项链,搭配,锁骨链,百搭,叠搭', '提供多种搭配方案并引导参考', 86
  UNION ALL SELECT 'fashion_accessories', '墨镜偏光吗钓鱼能戴吗', '亲，这款墨镜是偏光镜片，可以消除水面反光，钓鱼完全可以戴。偏光镜片能过滤眩光让视野更清晰，看鱼漂更清楚。镜片颜色是灰色不偏色。开车户外运动钓鱼都适用。已售上千副偏光反馈很好。支持退换不合适可以换。有问题随时联系我处理！', '墨镜,偏光,钓鱼,眩光,户外', '说明偏光性能及钓鱼适用性', 88
  UNION ALL SELECT 'fashion_accessories', '帽子能调节大小吗', '您好！这款帽子后边有金属调节扣，可以调节头围大小。头围54到60cm都能戴，头大头小都能找到合适的尺寸。调节扣金属质感很好耐用不易坏。帽子调节后不会松脱稳固佩戴。已售上千顶调节反馈很好。支持退换不合适可以换。有问题随时联系我！', '帽子,调节,头围,调节扣,尺寸', '说明可调节性及适用头围', 84
  UNION ALL SELECT 'fashion_accessories', '围巾多少钱能便宜点吗', '亲，这款已经是实在价了面料做工都很好。您要是诚心要我给您抹个零再送您一个同品牌收纳袋。这个品质这个价格真的很良心了您可以比比看。咱们做生意靠回头客不坑人。您看行就拍不行也不强求交个朋友嘛。有什么需要随时联系我！已售800多条价格反馈很好。', '砍价,价格,赠品,诚意,成交', '适度让利加赠品促成交易', 85
  UNION ALL SELECT 'fashion_accessories', '手表走时准吗机械还是石英', '您好！这款手表是石英表，走时精准每月误差不超过15秒，比机械表更准更省心。石英表不用上链换电池就行，一节电池用2到3年。机芯是进口机芯品质稳定。已售500多块走时反馈很好。要是有走时问题联系我们包退换。放心拍，品质有保障！', '手表,走时,石英,精准,机芯', '说明走时性能及机芯类型', 87
  UNION ALL SELECT 'fashion_accessories', '项链会不会过敏皮肤敏感能戴吗', '亲，这款项链是S925银的，亲肤性好不过敏，皮肤敏感也能戴。S925银是国际标准银饰材质不含镍不会引起过敏。要是不小心过敏了联系我们包退换。项链扣子也是S925银的不会过敏。已售600多条敏感肌反馈很好。放心拍，质量有保障！', '项链,过敏,S925银,亲肤,敏感肌', '说明材质亲肤性并承诺售后', 88
  UNION ALL SELECT 'fashion_accessories', '墨镜能配近视镜片吗', '您好！这款墨镜可以配近视镜片哦~您把近视度数和散光度数告诉我，我帮您定制近视镜片。也可以拿去眼镜店配片，镜框尺寸适合大多数镜片。近视墨镜开车户外都方便。已售上千副配片反馈很好。定制镜片需要加收费用。支持退换不合适可以换。有问题联系我！', '墨镜,近视,配片,定制,度数', '说明配近视镜片可行性及流程', 85
  UNION ALL SELECT 'fashion_accessories', '帽子搭配什么衣服好看', '亲，这款帽子很百搭哦~搭T恤休闲日常，搭衬衫文艺清新，搭卫衣运动活力。帽子是棒球帽款式不挑衣服风格不挑男女。颜色是黑色百搭不挑衣服颜色。我拍了三种搭配效果图您可以参考。已售上千顶搭配反馈很好。支持退换搭配不满意可以换！有问题随时联系我处理。', '帽子,搭配,棒球帽,百搭,休闲', '提供多种搭配方案并引导参考', 85
  UNION ALL SELECT 'fashion_accessories', '围巾洗涤要注意什么', '您好！这款围巾建议冷水手洗或放洗衣袋轻柔机洗。别用热水别漂白别拧干，自然晾干别暴晒。仿羊绒面料好打理但别和粗糙衣物混洗容易勾丝。洗后稍微整理下平铺晾干就好。要是有褶皱蒸汽熨低温熨一下就平整。已售800多条洗后反馈很好。有问题联系我！', '围巾,洗涤,机洗,仿羊绒,保养', '给出详细洗护建议避免损坏', 84
  UNION ALL SELECT 'fashion_accessories', '手表表盘多大合适', '亲，这款手表表盘直径40mm，是男士黄金尺寸不挑手腕。手腕细的选38mm，手腕粗的选42mm。40mm是最百搭的尺寸大多数人戴都好看。表盘厚度9mm轻薄不显笨重。我拍了佩戴效果图您可以看下大小。已售500多块表盘反馈很好。支持退换不合适可以换！', '手表,表盘,尺寸,直径,百搭', '说明表盘尺寸并给选表建议', 85
  UNION ALL SELECT 'fashion_accessories', '项链是什么款式百搭吗', '您好！这款项链是简约锁骨链款式，没有多余装饰简洁大方，百搭不挑衣服不挑场合。日常佩戴通勤上班休闲约会都适合。简约款式最不容易过时今年戴明年戴都好看。已售600多条款式反馈很好。支持退换款式不满意可以换。有问题随时联系我处理！', '项链,款式,简约,百搭,锁骨链', '说明款式特点及百搭性', 86
  UNION ALL SELECT 'fashion_accessories', '墨镜有几种颜色哪个好看', '亲，这款墨镜有黑色、茶色、灰色三种镜片颜色。黑色经典百搭最热门不挑人，茶色显白显气质适合女生，灰色不偏色最真实适合开车。三种都是经典颜色不挑脸型。我拍了每种颜色实物图您可以对比下。黑色库存充足当天发，其他颜色库存不多了。支持退换颜色不满意可以换！', '墨镜,颜色,镜片,百搭,库存', '推荐颜色并说明库存情况', 85
  UNION ALL SELECT 'fashion_accessories', '帽子防晒效果怎么样UPF多少', '您好！这款帽子UPF50+防晒指数，可以阻挡98%的紫外线。帽檐宽度7cm足够遮住脸部和脖子。棉布面料做了防紫外线处理。UPF50+是纺织品最高防晒等级。已售上千顶防晒反馈很好。夏天户外戴完全OK。支持退换不合适可以换。有问题随时联系我！', '帽子,防晒,UPF50,紫外线,帽檐', '说明防晒等级及效果', 88
  UNION ALL SELECT 'fashion_accessories', '围巾长度多少能绕几圈', '亲，这款围巾长度180cm宽度70cm。可以绕一圈休闲随意，绕两圈保暖显层次，也可以对折穿过去显设计感。长度足够大多数绕法。围巾做了加厚处理保暖性好。已售800多条尺寸反馈很好。我拍了不同绕法效果图您可以参考。支持退换不合适可以换！', '围巾,长度,绕法,尺寸,保暖', '说明尺寸及不同绕法', 84
  UNION ALL SELECT 'fashion_accessories', '手表是正品吗支持验货吗', '您好！正品支持专柜验货假一赔十！您可以拿去专柜对比或者扫码验证防伪，有问题全包退邮费我都出。我们做长久生意不干一锤子买卖。吊牌保修卡包装都齐全您收到一看就知道。已售500多块正品问题零投诉。放心拍，有任何疑问随时找我！', '手表,正品,验货,假一赔十,防伪', '承诺正品验货并承担退换邮费', 91
